use vstd::prelude::*;

verus! {

fn empty(n: u8) -> (result: Vec<f64>)
    ensures
        result.len() == n as nat,
{
    let mut v: Vec<f64> = Vec::new();
    let target: usize = n as usize;

    while v.len() < target
        invariant
            v.len() <= target,
            target == n as usize,
        decreases
            target - v.len(),
    {
        // No constraints on the values; any f64 is fine.
        v.push(0.0);
    }

    // At loop exit, v.len() >= target, and invariant gives v.len() <= target.
    // So v.len() == target.
    assert(v.len() == target);

    v
}

} // verus!

